CREATE TABLE `file_metadata` (
	`file_id` text NOT NULL,
	`key` text NOT NULL,
	`value` text NOT NULL,
	CONSTRAINT `file_metadata_pk` PRIMARY KEY(`file_id`, `key`),
	CONSTRAINT `fk_file_metadata_file_id_files_id_fk` FOREIGN KEY (`file_id`) REFERENCES `files`(`id`) ON DELETE CASCADE
);
CREATE TABLE `files` (
	`id` text PRIMARY KEY,
	`source` text NOT NULL,
	`key` text NOT NULL
);
CREATE UNIQUE INDEX `files_source_key` ON `files` (`source`,`key`);
